 r=c.request.post('/api/workspace/improvement-detail',data=body,headers={'Origin':B});assert r.ok,r.text();saved=r.json()['record'];expected=round(float(item['deduction_amount'])*0.2,1);assert float(saved['bonus_score'])==expected;r=c.request.get('/api/workspace/inspection-detail?id='+master['id']);assert len(r.json()['improvements'])==2 and float(r.json()['record']['improvement_bonus'])==expected;assert abs(float(r.json()['record']['total_score'])-(float(master['total_score'])+expected))<0.001;assert c.request.post('/api/workspace/improvement-detail',data=body,headers={'Origin':B}).ok;assert c.request.post('/api/workspace/improvement-detail',data={**body,'description':'changed'},headers={'Origin':B}).status==409;passed('percentage bonus updates master once and replay cannot overwrite')
 target=items[1];page=c.new_page();page.set_default_timeout(15000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('/workspace/index.html',wait_until='networkidle');page.get_by_label('搜尋功能').fill('待改善追蹤');page.get_by_role('navigation').get_by_role('button',name='待改善追蹤 新版').click();panel=page.locator('[role=tabpanel]:visible');expect(panel.get_by_role('heading',name='待改善追蹤')).to_be_visible();row=panel.locator('tbody tr').filter(has_text=date).filter(has_text=target['item_name']);row.get_by_role('button',name='查看與回報').click();edit=page.locator('[role=tabpanel]:visible');expect(edit.get_by_role('heading',name='改善項目與回報')).to_be_visible();edit.get_by_role('button',name='查看問題照片',exact=False).click();expect(page.get_by_alt_text('改善照片預覽')).to_be_visible();page.get_by_role('button',name='關閉照片').click();edit.get_by_label('改善說明',exact=True).fill('Vue 瀏覽器實際改善回報');edit.get_by_label('上傳改善照片',exact=True).set_input_files({'name':'improved.png','mimeType':'image/png','buffer':png});expect(edit.get_by_alt_text('改善照片 1',exact=True)).to_be_visible();passed('native detail displays issue photo and accepts compressed improvement photo')
