 edit.get_by_role('button',name='提交改善回報',exact=True).click();page.get_by_role('button',name='確認提交').click();expect(edit.get_by_text('改善內容已送出',exact=False)).to_be_visible();expect(edit.get_by_role('button',name='提交改善回報',exact=True)).to_have_count(0);edit.get_by_role('button',name='查看改善照片',exact=True).click();expect(page.get_by_alt_text('改善照片預覽')).to_be_visible();page.get_by_role('button',name='關閉照片').click();assert not errors,errors;page.screenshot(path='.tmp-check/improvement-submitted-desktop.png',full_page=True);page.set_viewport_size({'width':390,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path='.tmp-check/improvement-submitted-mobile.png',full_page=True);passed('successful submission locks form and persisted photos remain viewable on desktop and mobile');browser.close()
